1	package relayproof
2	
3	import (
4		"bytes"
5		"strings"
6		"testing"
7		"unicode/utf8"
8	)
9	
10	// Precedence coverage for lines where character corruption meets other
11	// problems. The normalizer checks whole-line character integrity before
12	// parsing JSON and validating fields, so the failure reason the user sees is
13	// decided by that order, never by where the problems happen to sit in the
14	// line: invalid UTF-8 bytes outrank unpaired \uXXXX surrogate escapes, and
15	// either outranks duplicate top-level keys and field validation. Each
16	// failing line yields exactly one result record — line, ok:false, one error,
17	// no event — and corrupted bytes are never repaired into replacement
18	// characters and handed to the field logic.
19	
20	// expectPrecedenceFailure asserts the single input line fails with one error
21	// record whose message contains every marker in contains and none in
22	// excludes, carries no event, and holds exactly the keys line/ok/error. The
23	// serialized output must stay valid UTF-8 and must never gain a U+FFFD the
24	// user did not write: corruption is reported, not repaired.
25	func expectPrecedenceFailure(t *testing.T, input string, contains, excludes []string) string {
26		t.Helper()
27		var out bytes.Buffer
28		failures, err := NormalizeReader(strings.NewReader(input), &out)
29		if err != nil {
30			t.Fatalf("a bad log line is not a stream error, got %v", err)
31		}
32		if failures != 1 {
33			t.Fatalf("the corrupted line must count as one failure, got %d", failures)
34		}
35		if !utf8.Valid(out.Bytes()) {
36			t.Fatalf("output must be valid UTF-8 even for corrupted input: %q", out.Bytes())
37		}
38		if bytes.Contains(out.Bytes(), []byte("�")) {
39			t.Fatalf("corrupted input must not be rewritten with replacement characters: %q", out.Bytes())
40		}
41		results := decodeResults(t, out.Bytes())
42		if len(results) != 1 {
43			t.Fatalf("expected exactly one result, got %#v", results)
44		}
45		r := results[0]
46		if r["line"] != float64(1) || r["ok"] != false {
47			t.Fatalf("corrupted line must fail as line 1: %#v", r)
48		}
49		if _, exists := r["event"]; exists {
50			t.Fatalf("corrupted line must not emit an event: %#v", r)
51		}
52		if len(r) != 3 {
53			t.Fatalf("a failure record carries exactly line, ok and one error, got %#v", r)
54		}
55		msg, _ := r["error"].(string)
56		if msg == "" {
57			t.Fatalf("corrupted line must explain itself: %#v", r)
58		}
59		if !utf8.ValidString(msg) {
60			t.Fatalf("error message must be valid UTF-8, got %q", msg)
61		}
62		for _, marker := range contains {
63			if !strings.Contains(msg, marker) {
64				t.Fatalf("error %q must contain %q", msg, marker)
65			}
66		}
67		for _, marker := range excludes {
68			if strings.Contains(msg, marker) {
69				t.Fatalf("error %q must not contain %q", msg, marker)
70			}
71		}
72		return msg
73	}
74	
75	// Any invalid UTF-8 byte on the line decides the failure reason, no matter
76	// what else is wrong with the same line and no matter where the byte sits
77	// relative to the other problem.
78	func TestNormalizeInvalidUTF8WinsOverOtherProblems(t *testing.T) {
79		cases := []struct {
80			name  string
81			input string
82		}{
83			// The escape problem comes first in the line, the invalid byte
84			// later: position must not let the escape win.
85			{"unpaired escape before invalid byte", `{"timestamp":"2026-01-02T00:00:00Z","action":"\uD800` + "\xff" + `"}`},
86			{"invalid byte before unpaired escape", `{"timestamp":"2026-01-02T00:00:00Z","action":"` + "\xff" + `\uD800"}`},
87			{"invalid byte with invalid timestamp", `{"timestamp":"not-a-time","action":"a` + "\xff" + `"}`},
88			{"invalid byte with duplicate top-level key", `{"timestamp":"2026-01-02T00:00:00Z","action":"a","action":"` + "\xff" + `"}`},
89			{"invalid byte with escape, timestamp and duplicate problems", `{"timestamp":"not-a-time","action":"\uD800` + "\xff" + `","action":"b"}`},
90		}
91		for _, tc := range cases {
92			t.Run(tc.name, func(t *testing.T) {
93				expectPrecedenceFailure(t, tc.input,
94					[]string{"UTF-8"},
95					[]string{"surrogate", "escape", "timestamp", "duplicate"})
96			})
97		}
98	}
99	
100	// With the raw bytes legal, an unpaired surrogate escape anywhere in the
101	// document — a mapped value, a field name, or an unknown field's nested
102	// object or array — decides the failure reason ahead of timestamp validation
103	// and the duplicate top-level key rule.
104	func TestNormalizeUnpairedEscapeWinsOverFieldProblems(t *testing.T) {
105		cases := []struct {
106			name  string
107			input string
108		}{
109			{"lone high surrogate in action with invalid timestamp", `{"timestamp":"not-a-time","action":"\uD800"}`},
110			{"lone low surrogate in action with invalid timestamp", `{"timestamp":"not-a-time","action":"act\uDC00ion"}`},
111			{"reversed pair in action with invalid timestamp", `{"timestamp":"not-a-time","action":"\uDC00\uD800"}`},
112			{"high surrogate in field name with duplicate key", `{"timestamp":"2026-01-02T00:00:00Z","action":"a","no\uD800te":"x","action":"b"}`},
113			{"low surrogate in nested extra object with invalid timestamp", `{"timestamp":"not-a-time","action":"a","extra":{"k":"\uDC00"}}`},
114			{"high surrogate in nested extra array with duplicate key", `{"timestamp":"2026-01-02T00:00:00Z","action":"a","action":"b","list":["ok","\uDBFF"]}`},
115		}
116		for _, tc := range cases {
117			t.Run(tc.name, func(t *testing.T) {
118				expectPrecedenceFailure(t, tc.input,
119					[]string{"unpaired", "surrogate"},
120					[]string{"UTF-8", "timestamp", "duplicate"})
121			})
122		}
123	}
124	
125	// Repairing the same log one character problem at a time must move the
126	// reported reason through the precedence order: invalid bytes first, then
127	// the unpaired escape, then the invalid timestamp, and only a fully clean
128	// line succeeds. The character check neither hides the later problems nor
129	// turns corrupted input into legal characters for the field logic.
130	func TestNormalizeCharsetRepairProgression(t *testing.T) {
131		stages := []struct {
132			name     string
133			input    string
134			contains []string
135			excludes []string
136		}{
137			{"invalid byte plus unpaired escape plus invalid timestamp",
138				`{"timestamp":"not-a-time","action":"\uD800` + "\xff" + `"}`,
139				[]string{"UTF-8"}, []string{"surrogate", "timestamp"}},
140			{"bytes repaired, escape still unpaired",
141				`{"timestamp":"not-a-time","action":"\uD800"}`,
142				[]string{"surrogate"}, []string{"UTF-8", "timestamp"}},
143			{"escape repaired, timestamp still invalid",
144				`{"timestamp":"not-a-time","action":"ok"}`,
145				[]string{"timestamp"}, []string{"UTF-8", "surrogate"}},
146		}
147		for _, stage := range stages {
148			t.Run(stage.name, func(t *testing.T) {
149				expectPrecedenceFailure(t, stage.input, stage.contains, stage.excludes)
150			})
151		}
152	
153		t.Run("all character problems repaired", func(t *testing.T) {
154			results := runNormalize(t, `{"timestamp":"2026-01-02T00:00:00Z","action":"ok"}`)
155			if len(results) != 1 || results[0]["ok"] != true {
156				t.Fatalf("the fully repaired line must succeed, got %#v", results)
157			}
158			if got := eventOf(t, results[0])["action"]; got != "ok" {
159				t.Fatalf("the repaired action must survive, got %v", got)
160			}
161		})
162	}
163	
164	// Once the characters are legal the character check steps aside completely:
165	// a duplicate top-level key still fails by the original duplicate rule, and
166	// an invalid timestamp still fails field validation — the integrity check
167	// must not make these later problems disappear.
168	func TestNormalizeCharacterCleanLinesKeepLaterFailures(t *testing.T) {
169		t.Run("duplicate top-level key", func(t *testing.T) {
170			expectPrecedenceFailure(t,
171				`{"timestamp":"2026-01-02T00:00:00Z","action":"a","action":"a"}`,
172				[]string{"duplicate", FieldAction},
173				[]string{"UTF-8", "surrogate"})
174		})
175		t.Run("duplicate key with legal paired escapes", func(t *testing.T) {
176			expectPrecedenceFailure(t,
177				`{"timestamp":"2026-01-02T00:00:00Z","action":"`+escGrinning+`","action":"a"}`,
178				[]string{"duplicate", FieldAction},
179				[]string{"UTF-8", "surrogate"})
180		})
181		t.Run("invalid timestamp", func(t *testing.T) {
182			expectPrecedenceFailure(t,
183				`{"timestamp":"2026-13-02T00:00:00Z","action":"a"}`,
184				[]string{FieldTimestamp},
185				[]string{"UTF-8", "surrogate", "duplicate"})
186		})
187	}
188	
189	// Legal lookalikes sharing one line with each other must not be mistaken for
190	// corruption: a correctly paired surrogate escape, a literal U+FFFD the user
191	// wrote, and uD800 appearing as plain text behind an escaped backslash all
192	// pass, with the unknown field's text and nested structure kept in extra.
193	func TestNormalizeLegalLookalikesSharingOneLine(t *testing.T) {
194		input := `{"timestamp":"2026-01-02T00:00:00Z","action":"` + escGrinning + `",` +
195			`"note":"\\uD800","mark":"�","nested":{"pair":"` + escGrinning + `","list":["\\uD800","�"]}}`
196		results := runNormalize(t, input)
197		if len(results) != 1 || results[0]["ok"] != true {
198			t.Fatalf("legal lookalikes must succeed, got %#v", results)
199		}
200		if got := eventOf(t, results[0])["action"]; got != "😀" {
201			t.Fatalf("paired escape in a mapped field must decode to the emoji, got %v", got)
202		}
203		extra := extraOf(t, results[0])
204		if extra["note"] != `\uD800` {
205			t.Fatalf(`escaped-backslash text must stay the plain text \uD800, got %v`, extra["note"])
206		}
207		if extra["mark"] != "�" {
208			t.Fatalf("a literal U+FFFD is valid input, got %v", extra["mark"])
209		}
210		nested, ok := extra["nested"].(map[string]any)
211		if !ok {
212			t.Fatalf("nested unknown structure must be preserved in extra, got %#v", extra["nested"])
213		}
214		if nested["pair"] != "😀" {
215			t.Fatalf("nested paired escape must decode, got %v", nested["pair"])
216		}
217		list, ok := nested["list"].([]any)
218		if !ok || len(list) != 2 || list[0] != `\uD800` || list[1] != "�" {
219			t.Fatalf("nested array text must survive verbatim, got %#v", nested["list"])
220		}
221	}
