209		// Inputs Go's time.Parse rewrites (pad, comma, truncate, carry) must
210		// all fail outright instead of yielding a successful event.
211		bad := []string{
212			"2026-01-02T5:04:05Z",             // single-digit hour
213			"2026-01-02T15:4:05Z",             // single-digit minute
214			"2026-01-02T15:04:5Z",             // single-digit second
215			"2026-01-02T15:04:05,1Z",          // comma decimal separator
216			"2026-01-02T15:04:05,1234567890Z", // 10 fractional digits, comma
217			"2026-01-02T15:04:05.1234567890Z", // 10 fractional digits, dot
218			"2026-01-02T15:04:05+24:00",       // offset hour out of range
219			"2026-01-02T15:04:05-24:00",
220			"2026-01-02T15:04:05+00:60", // offset minute carried by time.Parse
221			"2026-01-02T15:04:05+24:60",
222			"2026-01-02T24:04:05Z", // wall-clock hour out of range
223			"2026-01-02T15:60:05Z",
224			"2026-01-02T15:04:60Z",
225		}
226		for _, in := range bad {
227			for _, wrapper := range []string{
228				`{"timestamp":"` + in + `","action":"a"}`,
229				`{"time":"` + in + `","action":"a"}`,
230			} {
231				results := runNormalize(t, wrapper)
232				if results[0]["ok"] != false {
233					t.Fatalf("timestamp %q must fail, got %#v", in, results[0])
234				}
235				if _, exists := results[0]["event"]; exists {
236					t.Fatalf("rejected timestamp %q must not emit a partial event", in)
237				}
238				msg, _ := results[0]["error"].(string)
239				if !strings.Contains(msg, FieldTimestamp) {
240					t.Fatalf("error for %q must name %q, got %q", in, FieldTimestamp, msg)
241				}
242			}
243		}
244	}
