253	// their legal JSON escapes (\u000B, \u000F... \u000C) are ordinary content:
254	// the decoded control characters must be preserved in the unknown field's
255	// extra value, not confused with illegal framing outside the string.
256	func TestNormalizeEscapedControlWhitespaceInsideExtraStringsPreserved(t *testing.T) {
257		cases := []struct {
258			name    string
259			escaped string // JSON token text, including surrounding quotes
260			want    string // decoded Go string that must land in extra
261		}{
262			{"escaped vertical tab", `"\u000B"`, "\x0b"},
263			{"escaped form feed", `"\u000C"`, "\x0c"},
264			{"escaped controls around text", `"\u000Bnote\u000C"`, "\x0bnote\x0c"},
265			{"both escapes with edges", `" \u000B\u000C "`, " \x0b\x0c "},
266		}
267		for _, tc := range cases {
268			t.Run(tc.name, func(t *testing.T) {
269				input := `{"timestamp":"2026-01-02T00:00:00Z","action":"a","note":` + tc.escaped + `}`
270				results := runNormalize(t, input)
271				if len(results) != 1 || results[0]["ok"] != true {
272					t.Fatalf("legal \\uXXXX escapes inside a string must be accepted, got %#v", results)
273				}
274				if got := extraOf(t, results[0])["note"]; got != tc.want {
275					t.Fatalf("decoded control character must be preserved in extra, got %q want %q", got, tc.want)
276				}
277				// The serialized event must carry the character back as a proper
278				// JSON escape (control bytes never appear raw in JSON text).
279				raw := runNormalizeRaw(t, input)
280				if !strings.Contains(raw, `\u000`) {
281					t.Fatalf("control content must round-trip as a JSON escape in output, got %s", raw)
282				}
283			})
284		}
285	}
286	
287	// The in-string protection must not extend to the mapped action field: its
288	// existing rule trims Unicode whitespace from both ends. Ordinary JSON
289	// whitespace around an action is removed, and an action that is only special
290	// whitespace is still rejected as empty — preserving unknown-field content
291	// is not a behavior change for action.
292	func TestNormalizeActionTrimRuleUnchanged(t *testing.T) {
293		t.Run("ordinary spaces around action still trimmed", func(t *testing.T) {
294			results := runNormalize(t, `{"timestamp":"2026-01-02T00:00:00Z","action":"  login  "}`)
295			if results[0]["ok"] != true || eventOf(t, results[0])["action"] != "login" {
296				t.Fatalf("ordinary whitespace around action must still be trimmed: %#v", results[0])
297			}
298		})
299		t.Run("no-break spaces around action still trimmed", func(t *testing.T) {
300			results := runNormalize(t, `{"timestamp":"2026-01-02T00:00:00Z","action":`+
301				jsonString(noBreakSpace+"login"+noBreakSpace)+`}`)
302			if results[0]["ok"] != true || eventOf(t, results[0])["action"] != "login" {
303				t.Fatalf("strings.TrimSpace trimming of action must be unchanged, got %#v", results[0])
304			}
305		})
306		t.Run("ideographic spaces around action still trimmed", func(t *testing.T) {
307			results := runNormalize(t, `{"timestamp":"2026-01-02T00:00:00Z","action":`+
308				jsonString(ideographicSpace+"login"+ideographicSpace)+`}`)
309			if results[0]["ok"] != true || eventOf(t, results[0])["action"] != "login" {
310				t.Fatalf("strings.TrimSpace trimming of action must be unchanged, got %#v", results[0])
311			}
312		})
313		t.Run("special-whitespace-only action still empty", func(t *testing.T) {
314			for _, action := range []string{noBreakSpace, ideographicSpace, noBreakSpace + ideographicSpace} {
315				results := runNormalize(t, `{"timestamp":"2026-01-02T00:00:00Z","action":`+jsonString(action)+`}`)
316				if results[0]["ok"] != false {
317					t.Fatalf("whitespace-only action must fail even for special spaces, got %#v", results[0])
318				}
319				if msg, _ := results[0]["error"].(string); !strings.Contains(msg, FieldAction) {
320					t.Fatalf("empty-action error must name %q, got %q", FieldAction, msg)
321				}
322			}
323		})
324		t.Run("same special spaces are content only in the unknown field", func(t *testing.T) {
325			input := `{"timestamp":"2026-01-02T00:00:00Z","action":` +
326				jsonString(noBreakSpace+"go"+ideographicSpace) + `,"note":` +
327				jsonString(noBreakSpace+"go"+ideographicSpace) + `}`
328			results := runNormalize(t, input)
329			if results[0]["ok"] != true {
330				t.Fatalf("line must succeed, got %#v", results[0])
331			}
332			if got := eventOf(t, results[0])["action"]; got != "go" {
333				t.Fatalf("action edges must be trimmed, got %q", got)
334			}
335			if got := extraOf(t, results[0])["note"]; got != noBreakSpace+"go"+ideographicSpace {
336				t.Fatalf("unknown-field edges must be preserved, got %q", got)
337			}
338		})
339	}
340	
341	// White-box pin for the exact trim set: trimJSONWhitespace must remove only
342	// the four RFC 8259 whitespace bytes from the document edges. It must keep
343	// every other whitespace-looking byte so the decoder gets a chance to reject
344	// it, and it must not touch interior bytes at all.
345	func TestTrimJSONWhitespaceSet(t *testing.T) {
346		const doc = `{"a":1}`
347	
348		t.Run("exactly the four JSON whitespace bytes are trimmed", func(t *testing.T) {
349			for _, c := range []byte{' ', '\t', '\r', '\n'} {
350				raw := bytes.Join([][]byte{{c, c}, []byte(doc), {c}}, nil)
351				if got := trimJSONWhitespace(raw); string(got) != doc {
352					t.Fatalf("byte %q must be trimmed from the edges, got %q", c, got)
353				}
354			}
355		})
356	
357		t.Run("all other whitespace-looking bytes survive at the edges", func(t *testing.T) {
358			// Each prefix is one complete non-JSON-whitespace rune (plus one
359			// single-byte control); none of their bytes may be in the trim set.
360			for _, prefix := range []string{
361				"\x0b",             // vertical tab
362				"\x0c",             // form feed
363				string(rune(0x85)), // U+0085 next line
364				noBreakSpace,       // U+00A0
365				ideographicSpace,   // U+3000
366			} {
367				raw := append([]byte(prefix), []byte(doc)...)
368				trimmed := trimJSONWhitespace(raw)
369				if len(trimmed) != len(raw) || !bytes.HasPrefix(trimmed, []byte(prefix)) {
370					t.Fatalf("rune %q must not be trimmed like JSON whitespace, got %q", prefix, trimmed)
371				}
372			}
373		})
374	
375		t.Run("interior whitespace is never examined", func(t *testing.T) {
376			// Only the surrounding bytes are in scope; bytes inside the document
377			// pass through untouched even when they include illegal separators
378			// (the decoder, not the trim, is what rejects those).
379			raw := []byte(" " + doc + verticalTab + doc + " ")
380			trimmed := trimJSONWhitespace(raw)
381			if string(trimmed) != doc+verticalTab+doc {
382				t.Fatalf("only edge whitespace may be removed, got %q", trimmed)
383			}
384		})
385	
386		t.Run("empty and whitespace-only input", func(t *testing.T) {
387			if got := trimJSONWhitespace(nil); len(got) != 0 {
388				t.Fatalf("nil input must trim to empty, got %q", got)
389			}
390			// A line of only non-JSON whitespace is trimmed down to those same
391			// bytes, never to empty: it must reach the decoder and fail there
392			// rather than looking like a blank line.
393			illegalOnly := []byte(verticalTab + formFeed + noBreakSpace + ideographicSpace)
394			if got := trimJSONWhitespace(illegalOnly); !bytes.Equal(got, illegalOnly) {
395				t.Fatalf("illegal-whitespace-only line must survive trimming, got %q", got)
396			}
397			if !utf8.Valid(illegalOnly) {
398				t.Fatalf("test setup: illegal-only line must be valid UTF-8")
399			}
400		})
401	}
402	
403	// The two whitespace rules live on different layers and must not be
404	// conflated.
405	//
406	// NormalizeLine is the strict JSON-document boundary: a line whose only
407	// content is non-JSON whitespace is not a JSON object and fails there with a
408	// syntax reason, regardless of how TrimSpace would classify it.
409	//
410	// NormalizeReader keeps its pre-existing, broader blank-line rule
411	// (strings.TrimSpace on the raw physical line): a line made solely of
412	// whitespace — including U+000B, U+000C, U+00A0 and U+3000 — occupies a
413	// physical line number but produces no record and no failure, exactly like a
414	// line of ordinary spaces. The document-boundary protection therefore bites
415	// on real event lines (an object framed with such bytes), and the established
416	// blank-line behavior is unchanged.
417	func TestNormalizeWhitespaceOnlyLineLayeredBehavior(t *testing.T) {
418		illegalOnly := verticalTab + formFeed + noBreakSpace + ideographicSpace
419	
420		t.Run("NormalizeLine rejects non-JSON whitespace as a document", func(t *testing.T) {
421			r := NormalizeLine(1, []byte(illegalOnly))
422			if r.OK || r.Event != nil {
423				t.Fatalf("non-JSON whitespace is not a JSON object: %#v", r)
424			}
425			if !strings.Contains(r.Error, "invalid JSON") {
426				t.Fatalf("must be a JSON syntax error, got %q", r.Error)
427			}
428		})
429	
430		t.Run("NormalizeReader treats whitespace-only lines as blank rows", func(t *testing.T) {
431			// A legal log, a whitespace-only line (illegal chars included), and
432			// another legal log: the middle line keeps its line number but emits
433			// nothing and counts no failure.
434			input := legalJSONDocument + "\n" + illegalOnly + "\n" + legalJSONDocument + "\n"
435			var out bytes.Buffer
436			failures, err := NormalizeReader(strings.NewReader(input), &out)
437			if err != nil {
438				t.Fatalf("a healthy stream must not return an error, got %v", err)
439			}
440			if failures != 0 {
441				t.Fatalf("a whitespace-only line follows the existing blank rule and must not count, got %d", failures)
442			}
443			results := decodeResults(t, out.Bytes())
444			if len(results) != 2 {
445				t.Fatalf("the whitespace-only line must produce no record, got %#v", results)
446			}
447			if results[0]["line"] != float64(1) || results[1]["line"] != float64(3) {
448				t.Fatalf("the skipped line must still occupy physical line 2, got %#v", results)
449			}
450		})
451	}
452	
453	// Mixed stream: valid logs, logs framed with illegal separators, a log with
454	// content after the object, and ordinary blank lines. Each failure is
455	// confined to its own physical line — original line number, ok:false, a JSON
456	// reason, no event — surrounding valid logs keep their order, blank lines
457	// only occupy a number, the failure count covers only actual failure rows,
458	// and a healthy read/write is not a stream error.
459	func TestNormalizeIllegalSeparatorsInMixedStream(t *testing.T) {
460		input := "" +
461			legalJSONDocument + "\n" + // line 1: ok
462			verticalTab + legalJSONDocument + "\n" + // line 2: fail (illegal char before)
463			"\n" + // line 3: blank, no record
464			"   \t  \n" + // line 4: ordinary whitespace, no record
465			legalJSONDocument + noBreakSpace + "\n" + // line 5: fail (illegal char after)
466			`{"timestamp":"2026-01-02T00:00:00Z","action":"mid"}` + "\n" + // line 6: ok
467			`{"timestamp":"2026-01-02T00:00:00Z","action":` +
468			jsonString("a"+ideographicSpace+"b") +
469			`,"note":` + jsonString(ideographicSpace+"kept"+ideographicSpace) + "}\n" + // line 7: ok (spaces in strings)
470			`{"timestamp":"2026-01-02T00:00:00Z","action":"a",` + formFeed + `"x":1}` + "\n" + // line 8: fail (illegal char between members)
471			legalJSONDocument + `{"b":2}` + "\n" + // line 9: fail (trailing JSON value)
472			`{"timestamp":"2026-01-02T00:00:03Z","action":"last"}` + "\r\n" // line 10: ok, CRLF-terminated
473	
474		var out bytes.Buffer
475		failures, err := NormalizeReader(strings.NewReader(input), &out)
476		if err != nil {
477			t.Fatalf("per-line failures in a healthy stream must not be a stream error, got %v", err)
478		}
479		if failures != 4 {
480			t.Fatalf("exactly lines 2, 5, 8, 9 must count as failures, got %d", failures)
481		}
482	
483		results := decodeResults(t, out.Bytes())
484		if len(results) != 8 {
485			t.Fatalf("8 non-blank physical lines must yield 8 records (blanks yield none), got %#v", results)
486		}
487	
488		want := []struct {
489			line float64
490			ok   bool
491		}{
492			{1, true},
493			{2, false},
494			{5, false},
495			{6, true},
496			{7, true},
497			{8, false},
498			{9, false},
499			{10, true},
500		}
501		for i, w := range want {
502			if results[i]["line"] != w.line || results[i]["ok"] != w.ok {
503				t.Fatalf("record %d must be physical line %v ok=%v, got %#v", i, w.line, w.ok, results[i])
504			}
505		}
506	
507		for _, i := range []int{1, 2, 5, 6} {
508			r := results[i]
509			if _, exists := r["event"]; exists {
510				t.Fatalf("failed line %v must carry no event: %#v", r["line"], r)
511			}
512			if msg, _ := r["error"].(string); !strings.Contains(msg, "invalid JSON") {
513				t.Fatalf("failed line %v must give a JSON syntax reason, got %q", r["line"], msg)
514			}
515		}
516	
517		if got := eventOf(t, results[0])["action"]; got != "a" {
518			t.Fatalf("line 1 action mismatch: %#v", results[0])
519		}
520		if got := eventOf(t, results[3])["action"]; got != "mid" {
521			t.Fatalf("line 6 must follow failures in order, got action %v", got)
522		}
523		line7 := results[4]
524		if got := eventOf(t, line7)["action"]; got != "a"+ideographicSpace+"b" {
525			t.Fatalf("line 7 action must keep its in-string content, got %q", got)
526		}
527		if got := extraOf(t, line7)["note"]; got != ideographicSpace+"kept"+ideographicSpace {
528			t.Fatalf("line 7 unknown field must keep edge whitespace verbatim, got %q", got)
529		}
530		if got := eventOf(t, results[7])["action"]; got != "last" {
531			t.Fatalf("line 10 (CRLF) must still be processed after the failures, got action %v", got)
532		}
533	}
