package main

import (
	"fmt"
	"unicode/utf8"
)

func invalidUTF8Offset(raw []byte) int {
	for i := 0; i < len(raw); {
		_, size := utf8.DecodeRune(raw[i:])
		if size == 1 && raw[i] >= utf8.RuneSelf {
			return i
		}
		i += size
	}
	return -1
}

func hex4(b []byte) (int, bool) {
	v := 0
	for _, c := range b {
		v <<= 4
		switch {
		case c >= '0' && c <= '9':
			v |= int(c - '0')
		case c >= 'a' && c <= 'f':
			v |= int(c-'a') + 10
		case c >= 'A' && c <= 'F':
			v |= int(c-'A') + 10
		default:
			return 0, false
		}
	}
	return v, true
}

type esc struct{ code, off int }

func scanEscapes(raw []byte) (es []esc, bad *esc) {
	inString := false
	for i := 0; i < len(raw); i++ {
		c := raw[i]
		if !inString {
			if c == '"' {
				inString = true
			}
			continue
		}
		if c == '"' {
			inString = false
			continue
		}
		if c != '\\' {
			continue
		}
		if i+1 >= len(raw) || raw[i+1] != 'u' {
			i++
			continue
		}
		if i+6 > len(raw) {
			continue
		}
		code, ok := hex4(raw[i+2 : i+6])
		if !ok {
			continue
		}
		switch {
		case code >= 0xD800 && code <= 0xDBFF:
			if i+12 <= len(raw) && raw[i+6] == '\\' && raw[i+7] == 'u' {
				if low, ok := hex4(raw[i+8 : i+12]); ok && low >= 0xDC00 && low <= 0xDFFF {
					i += 11
					continue
				}
			}
			e := esc{code, i}
			return es, &e
		case code >= 0xDC00 && code <= 0xDFFF:
			e := esc{code, i}
			return es, &e
		default:
			i += 5
		}
	}
	return es, nil
}

const (
	escGrinning = "\\uD83D\\uDE00"
)

func show(name, line string) {
	trimmed := trim(line)
	off := invalidUTF8Offset([]byte(trimmed))
	_, bad := scanEscapes([]byte(trimmed))
	fmt.Printf("%-42s len=%d trimLen=%d utf8off=%d", name, len(line), len(trimmed), off)
	if bad != nil {
		fmt.Printf(" surrogate U+%04X @%d", bad.code, bad.off)
	} else {
		fmt.Printf(" surrogate=none")
	}
	fmt.Println()
}

func trim(s string) string {
	for len(s) > 0 && (s[0] == ' ' || s[0] == '\t' || s[0] == '\r' || s[0] == '\n') {
		s = s[1:]
	}
	for len(s) > 0 && (s[len(s)-1] == ' ' || s[len(s)-1] == '\t' || s[len(s)-1] == '\r' || s[len(s)-1] == '\n') {
		s = s[:len(s)-1]
	}
	return s
}

func main() {
	// UTF-8 cases (trimmed docs)
	show("ff in action ascii prefix", `{"timestamp":"2026-01-02T00:00:00Z","action":"log`+"\xff"+`in"}`)
	show("c3 28 in note", `{"timestamp":"2026-01-02T00:00:00Z","action":"a","note":"`+"\xc3\x28"+`"}`)
	show("truncated 3-byte in key", `{"timestamp":"2026-01-02T00:00:00Z","action":"a","no`+"\xe2\x80"+`te":"x"}`)
	show("truncated 4-byte in value", `{"timestamp":"2026-01-02T00:00:00Z","action":"`+"\xf0\x9f"+`"}`)
	show("truncated 2-byte at end", `{"timestamp":"2026-01-02T00:00:00Z","action":"a"}`+"\xc3")
	show("lone continuation after brace", `{"timestamp":"2026-01-02T00:00:00Z","action":"a"}`+"\x80")
	show("overlong c0 af in action", `{"timestamp":"2026-01-02T00:00:00Z","action":"`+"\xc0\xaf"+`"}`)
	show("ed a0 80 raw in nested extra", `{"timestamp":"2026-01-02T00:00:00Z","action":"a","extra":{"deep":["ok","`+"\xed\xa0\x80"+`"]}}`)
	show("chinese before ff", `{"timestamp":"2026-01-02T00:00:00Z","action":"登录`+"\xff"+`"}`)
	show("chinese+emoji before truncated", `{"timestamp":"2026-01-02T00:00:00Z","action":"用户😀`+"\xe2\x80"+`"}`)
	show("tabs inside before ff", `{"timestamp":	"2026-01-02T00:00:00Z"	,	"action":	"a`+"\xff"+`"}`)
	show("nested unknown utf8", `{"timestamp":"2026-01-02T00:00:00Z","action":"a","extra":{"deep":["ok","x`+"\xff"+`y"]}}`)
	show("both: escape early + ff late", `{"timestamp":"2026-01-02T00:00:00Z","action":"\uD800`+"\xff"+`"}`)
	show("both: ff early + escape late", `{"timestamp":"2026-01-02T00:00:00Z","action":"`+"\xff"+`\uD800"}`)

	// escape cases
