func hex4(b []byte) (int, bool) {
	v := 0
	for _, c := range b {
		v <<= 4
		switch {
		case c >= '0' && c <= '9': v |= int(c-'0')
		case c >= 'a' && c <= 'f': v |= int(c-'a')+10
		case c >= 'A' && c <= 'F': v |= int(c-'A')+10
		default: return 0, false
		}
	}
	return v, true
}
func scan(raw []byte) (int, int) {
	inString := false
	for i := 0; i < len(raw); i++ {
